-- 1 ter. Rayons du dossier -------------------------------------------------
-- `chapters.discipline` (migration 247) : le rayon de la matière auquel la
-- fiche appartient. La page matière en fait un onglet par rayon.
UPDATE public.chapters c SET discipline = v.discipline
