    ('9778c678-5350-5307-8efe-140b671cff8f'::uuid, '809d17b1-4ce3-542e-a547-26a1dba178f2'::uuid, 'Quel roi de France invite Léonard en 1516 ?', 'mcq', '["François Ier","Louis XII","Henri II","Charles VIII"]'::jsonb, 0, 'Il l’installe au Clos Lucé, près du château d’Amboise.', 5),
    ('a47c5473-341f-58d5-a5df-cf7aebcf14ea'::uuid, '809d17b1-4ce3-542e-a547-26a1dba178f2'::uuid, 'Léonard a réalisé la plupart des machines qu’il a dessinées.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce sont des projets, rarement construits de son vivant.', 6),
    ('89717bf0-c986-59f2-be96-1bd77853e75c'::uuid, '809d17b1-4ce3-542e-a547-26a1dba178f2'::uuid, 'Pourquoi Léonard incarne-t-il l’idéal humaniste ?', 'mcq', '["Il unit l’art, la technique et la science dans une même curiosité","Il a traduit la Bible","Il a fondé une université","Il a dirigé un État"]'::jsonb, 0, 'L’homme universel, capable dans tous les domaines.', 7),
    ('ec5ea219-b4c2-50fd-9d9a-2675dd99e97e'::uuid, '809d17b1-4ce3-542e-a547-26a1dba178f2'::uuid, 'En quelle année Léonard meurt-il ?', 'mcq', '["1519","1492","1547","1503"]'::jsonb, 0, 'À Amboise, au service du roi de France.', 8),
    ('5cb9e9d9-1d47-5e87-8373-e590b18cfc69'::uuid, 'ac60c1a9-41f8-56de-829b-2d7f9220247c'::uuid, 'D’où le roi absolu tient-il son pouvoir selon la doctrine du temps ?', 'mcq', '["De Dieu","Du peuple","Des états généraux","Du Parlement de Paris"]'::jsonb, 0, 'C’est la monarchie de droit divin.', 1),
    ('942f20c5-aab3-559d-b3be-4e6d61386d4d'::uuid, 'ac60c1a9-41f8-56de-829b-2d7f9220247c'::uuid, 'Le pouvoir absolu signifie-t-il un pouvoir sans aucune limite ?', 'mcq', '["Non : lois fondamentales, coutumes et privilèges le bornent","Oui, le roi peut tout","Oui, sauf en matière religieuse","Non, il est limité par une constitution écrite"]'::jsonb, 0, 'Absolu ne veut pas dire arbitraire.', 2),
    ('f1d560d6-8076-55a3-b5c5-2ef83d9308c0'::uuid, 'ac60c1a9-41f8-56de-829b-2d7f9220247c'::uuid, 'Quel ministre de Louis XIII crée les intendants ?', 'mcq', '["Richelieu","Sully","Colbert","Mazarin"]'::jsonb, 0, 'Des agents révocables envoyés dans les provinces au nom du roi.', 3),
    ('ca28b29e-ec5a-597e-83be-ee6bc2e2626a'::uuid, 'ac60c1a9-41f8-56de-829b-2d7f9220247c'::uuid, 'Qu’est-ce que la Fronde ?', 'mcq', '["Une révolte des parlements et des princes entre 1648 et 1653","Une guerre contre l’Espagne","Une révolte paysanne bretonne","Un complot protestant"]'::jsonb, 0, 'Elle marque durablement le jeune Louis XIV.', 4),
    ('dacc8d88-5efe-5cc4-94cb-ca0ea8fd7cf2'::uuid, 'ac60c1a9-41f8-56de-829b-2d7f9220247c'::uuid, 'En quelle année Louis XIV commence-t-il son règne personnel ?', 'mcq', '["1661","1643","1682","1685"]'::jsonb, 0, 'À la mort de Mazarin, il décide de gouverner sans principal ministre.', 5),
    ('1220f6c1-8e84-5005-8561-f60fc01d47cf'::uuid, 'ac60c1a9-41f8-56de-829b-2d7f9220247c'::uuid, 'Louis XIV réunit régulièrement les états généraux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils ne sont plus convoqués de 1614 à 1789.', 6),
    ('dfb9176f-155d-5288-8992-eb530a2cf0f5'::uuid, 'ac60c1a9-41f8-56de-829b-2d7f9220247c'::uuid, 'En quelle année la cour s’installe-t-elle à Versailles ?', 'mcq', '["1682","1661","1715","1670"]'::jsonb, 0, 'La noblesse y vit sous le regard permanent du roi.', 7),
    ('a6b7ec9c-80a4-5d21-9dd2-96d8f323f805'::uuid, 'ac60c1a9-41f8-56de-829b-2d7f9220247c'::uuid, 'À quoi sert l’étiquette de la cour ?', 'mcq', '["À hiérarchiser la noblesse et à la tenir sous le contrôle du roi","À réduire les dépenses de la cour","À former les officiers","À organiser la justice"]'::jsonb, 0, 'Un lever du roi est un acte politique.', 8),
    ('cab85316-e08d-5a9d-832d-501758e79f9b'::uuid, '2dd55ae4-ed07-553b-8dcd-cb88459fb8a3'::uuid, 'Quel principe fonde le mercantilisme ?', 'mcq', '["Vendre à l’étranger plus qu’on ne lui achète pour attirer les métaux précieux","Supprimer les droits de douane","Laisser faire le marché","Interdire le commerce extérieur"]'::jsonb, 0, 'La richesse mondiale y est vue comme une somme fixe.', 1),
    ('15c40f5c-6ac1-5ff6-b70b-dbddf6c93a5d'::uuid, '2dd55ae4-ed07-553b-8dcd-cb88459fb8a3'::uuid, 'Quelle fonction Colbert occupe-t-il auprès de Louis XIV ?', 'mcq', '["Contrôleur général des finances","Chancelier de France","Connétable","Archevêque de Paris"]'::jsonb, 0, 'De 1665 à 1683, il tient aussi la marine et les manufactures.', 2),
    ('b5129c3a-e301-5729-9e17-3e20ade0ed93'::uuid, '2dd55ae4-ed07-553b-8dcd-cb88459fb8a3'::uuid, 'Qu’est-ce qu’une manufacture royale ?', 'mcq', '["Un établissement de production privilégié et contrôlé par l’État","Un marché hebdomadaire","Un entrepôt portuaire","Une corporation d’artisans"]'::jsonb, 0, 'Gobelins, Saint-Gobain : qualité imposée, débouchés garantis.', 3),
    ('0cf1e4e5-ed70-51ab-88c4-6502a042c5b6'::uuid, '2dd55ae4-ed07-553b-8dcd-cb88459fb8a3'::uuid, 'Quel grand ouvrage reliant l’Atlantique à la Méditerranée est achevé en 1681 ?', 'mcq', '["Le canal du Midi","Le canal de Bourgogne","Le canal Saint-Martin","Le canal de Briare"]'::jsonb, 0, 'Conçu par Pierre-Paul Riquet.', 4),
    ('ed270911-879c-5491-afab-b4f37e48231c'::uuid, '2dd55ae4-ed07-553b-8dcd-cb88459fb8a3'::uuid, 'Quelle mesure de 1685 prive le royaume de nombreux artisans et négociants ?', 'mcq', '["La révocation de l’édit de Nantes","La création de la taille","La fermeture des ports","L’édit de Villers-Cotterêts"]'::jsonb, 0, 'Les protestants émigrent vers l’Angleterre, la Hollande et la Prusse.', 5),
    ('52f511a8-0cb4-50e1-bd35-c49cdd67b9a8'::uuid, '2dd55ae4-ed07-553b-8dcd-cb88459fb8a3'::uuid, 'La taille était payée par la noblesse et le clergé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils en sont exemptés : le poids retombe sur les paysans.', 6),
    ('4ed67328-0c8d-56a6-9c9d-04c460106bbf'::uuid, '2dd55ae4-ed07-553b-8dcd-cb88459fb8a3'::uuid, 'Pourquoi Colbert relève-t-il les tarifs douaniers en 1664 et 1667 ?', 'mcq', '["Pour protéger la production française de la concurrence étrangère","Pour financer Versailles","Pour plaire aux marchands hollandais","Pour réduire le prix du pain"]'::jsonb, 0, 'Le protectionnisme est le bras armé du mercantilisme.', 7),
    ('0128a4fc-4567-5c8a-8873-a2090a009593'::uuid, '2dd55ae4-ed07-553b-8dcd-cb88459fb8a3'::uuid, 'Qu’est-ce qui ruine finalement les efforts financiers de Colbert ?', 'mcq', '["Le coût des guerres de Louis XIV","La chute du commerce colonial","Une révolte des manufactures","La disparition du canal du Midi"]'::jsonb, 0, 'Les dépenses militaires absorbent l’essentiel des recettes.', 8),
    ('1cb5bb97-58ef-59fb-a367-822f168cc2d5'::uuid, 'ed3b44f1-3e4a-5ba7-a310-dc0f1358478a'::uuid, 'Quelles sont les deux grandes composantes de la noblesse d’Ancien Régime ?', 'mcq', '["La noblesse d’épée et la noblesse de robe","La noblesse de cour et la noblesse d’Église","Les ducs et les barons","Les seigneurs et les vassaux"]'::jsonb, 0, 'L’une vient du service militaire, l’autre des offices.', 1),
    ('d368ca84-1779-5e49-a941-a0f0e2f30cd4'::uuid, 'ed3b44f1-3e4a-5ba7-a310-dc0f1358478a'::uuid, 'Qu’est-ce que la vénalité des offices ?', 'mcq', '["La possibilité d’acheter une charge publique","L’impôt payé par les nobles","Le droit de rendre la justice","La vente des terres seigneuriales"]'::jsonb, 0, 'Elle remplit les caisses mais rend les titulaires difficiles à révoquer.', 2),
    ('1b630c3f-0b34-54b3-9acf-2407aafafd74'::uuid, 'ed3b44f1-3e4a-5ba7-a310-dc0f1358478a'::uuid, 'Qu’est-ce que le droit de remontrance ?', 'mcq', '["Le droit des parlements de critiquer un édit avant de l’enregistrer","Le droit du roi de casser un jugement","Le droit des paysans de pétitionner","Le droit d’appel devant le roi"]'::jsonb, 0, 'Il devient au XVIIIe siècle une arme d’opposition politique.', 3),
    ('0579174e-1329-5003-b355-b273c756f013'::uuid, 'ed3b44f1-3e4a-5ba7-a310-dc0f1358478a'::uuid, 'Comment le roi impose-t-il l’enregistrement d’un édit refusé ?', 'mcq', '["Par un lit de justice","Par une lettre de cachet","Par un édit de grâce","Par un concordat"]'::jsonb, 0, 'Le roi vient siéger en personne au parlement.', 4),
    ('a678adb4-618b-5689-afed-09970d9ba18e'::uuid, 'ed3b44f1-3e4a-5ba7-a310-dc0f1358478a'::uuid, 'Pourquoi les intendants ne sont-ils pas choisis dans la haute noblesse d’épée ?', 'mcq', '["Pour qu’ils dépendent entièrement du roi et soient révocables","Parce qu’ils sont élus","Parce que la noblesse refuse ces charges","Parce qu’ils doivent être étrangers"]'::jsonb, 0, 'Un agent sans base locale ne peut pas se rendre indépendant.', 5),
    ('a1a505e2-b702-5c85-8d7b-143556bfd987'::uuid, 'ed3b44f1-3e4a-5ba7-a310-dc0f1358478a'::uuid, 'La monarchie a réussi à supprimer les privilèges fiscaux de la noblesse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Toutes les tentatives échouent : c’est l’une des causes de 1789.', 6),
    ('2dc48b39-239c-582f-9850-b7b61a55b217'::uuid, 'ed3b44f1-3e4a-5ba7-a310-dc0f1358478a'::uuid, 'À quoi sert la cour de Versailles dans la politique royale ?', 'mcq', '["À tenir la noblesse par les pensions, les charges et l’étiquette","À former les intendants","À loger les parlementaires","À réunir les états généraux"]'::jsonb, 0, 'Une noblesse domestiquée coûte cher mais ne conspire plus.', 7),
    ('262154e0-106c-5fc5-bb12-d844f1f5252b'::uuid, 'ed3b44f1-3e4a-5ba7-a310-dc0f1358478a'::uuid, 'Quel événement de 1789 marque l’échec des réformes fiscales de la monarchie ?', 'mcq', '["La convocation des états généraux","La Fronde","La révocation de l’édit de Nantes","La journée des Dupes"]'::jsonb, 0, 'Faute de pouvoir réformer seul, le roi doit convoquer le royaume.', 8),
    ('8b22a9f7-c24c-538d-84bf-1d6a9f41908b'::uuid, 'a6beaea9-e988-5f8b-9150-b952dbe685b1'::uuid, 'Que garantit la Grande Charte de 1215 ?', 'mcq', '["Que le roi ne lève pas d’impôt sans l’accord de ses barons","La liberté de la presse","Le suffrage universel","La séparation des pouvoirs"]'::jsonb, 0, 'Le consentement à l’impôt est l’arme du Parlement.', 1),
    ('c10242cb-4578-5618-80b0-a73d9d1b375c'::uuid, 'a6beaea9-e988-5f8b-9150-b952dbe685b1'::uuid, 'Quel roi anglais est exécuté en 1649 ?', 'mcq', '["Charles Ier","Jacques II","Charles II","Guillaume III"]'::jsonb, 0, 'Jugé par ses propres sujets, ce qui stupéfie l’Europe.', 2),
    ('9d1adbc9-9695-5fb0-9d6f-e7f88723ccfb'::uuid, 'a6beaea9-e988-5f8b-9150-b952dbe685b1'::uuid, 'Qui dirige l’Angleterre après l’exécution de Charles Ier ?', 'mcq', '["Oliver Cromwell","Guillaume d’Orange","Robert Walpole","Jacques II"]'::jsonb, 0, 'République puis protectorat, qui déçoit et prépare la Restauration.', 3),
    ('190f68eb-0bbe-5900-a49a-54f1a48c7f3b'::uuid, 'a6beaea9-e988-5f8b-9150-b952dbe685b1'::uuid, 'Que se passe-t-il lors de la Glorieuse Révolution de 1688 ?', 'mcq', '["Le Parlement écarte Jacques II et appelle Guillaume d’Orange","Le roi dissout le Parlement","Cromwell prend le pouvoir","L’Écosse fait sécession"]'::jsonb, 0, 'Une révolution presque sans effusion de sang.', 4),
    ('c71db47b-e3b4-59d5-9eda-bedc86f862bb'::uuid, 'a6beaea9-e988-5f8b-9150-b952dbe685b1'::uuid, 'Que fixe le Bill of Rights de 1689 ?', 'mcq', '["Les limites du pouvoir royal face au Parlement","Le droit de vote pour tous","La liberté religieuse totale","L’abolition de la monarchie"]'::jsonb, 0, 'Ni impôt ni armée permanente sans le Parlement.', 5),
    ('2a2744f0-9acf-5743-8a4b-2286236aa96d'::uuid, 'a6beaea9-e988-5f8b-9150-b952dbe685b1'::uuid, 'L’habeas corpus protège contre la détention arbitraire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Voté en 1679, il oblige à présenter tout détenu à un juge.', 6),
    ('bdef9d6c-d19d-5fca-8b17-73b26026063c'::uuid, 'a6beaea9-e988-5f8b-9150-b952dbe685b1'::uuid, 'De quelles chambres le Parlement britannique est-il composé ?', 'mcq', '["Les Communes et les Lords","Le Sénat et l’Assemblée","Les états généraux","Le Conseil privé et la Chambre étoilée"]'::jsonb, 0, 'Deux chambres, aux recrutements très différents.', 7),
    ('3bfbeba2-5a47-5c6e-a853-8949add0bc70'::uuid, 'a6beaea9-e988-5f8b-9150-b952dbe685b1'::uuid, 'Le suffrage britannique du XVIIIe siècle est-il universel ?', 'mcq', '["Non, il est très restreint et inégalement réparti","Oui, pour tous les hommes","Oui, pour tous les adultes","Non, il n’existe pas d’élections"]'::jsonb, 0, 'Bourgs pourris et cens élevé : le principe précède l’égalité.', 8),
    ('ee62ee15-7814-53cc-990a-9172e83b260b'::uuid, 'b48f6d6f-aef1-5aa2-85da-d58cddd5376e'::uuid, 'Quel ouvrage Voltaire publie-t-il en 1734 après son séjour anglais ?', 'mcq', '["Les Lettres philosophiques","Candide","Le Contrat social","De l’esprit des lois"]'::jsonb, 0, 'Un éloge de l’Angleterre qui vaut critique de la France.', 1),
    ('98b48b67-ee83-5447-90ce-684b5b50ca1c'::uuid, 'b48f6d6f-aef1-5aa2-85da-d58cddd5376e'::uuid, 'Quelle idée Montesquieu tire-t-il de l’exemple britannique ?', 'mcq', '["La séparation des pouvoirs","Le suffrage universel","La souveraineté populaire","L’abolition de la monarchie"]'::jsonb, 0, 'Pour que le pouvoir arrête le pouvoir.', 2),
    ('e23a9906-2bb9-536a-9326-7f5152c8e7ce'::uuid, 'b48f6d6f-aef1-5aa2-85da-d58cddd5376e'::uuid, 'En quelle année paraît De l’esprit des lois ?', 'mcq', '["1748","1734","1690","1762"]'::jsonb, 0, 'Fruit de vingt ans de travail et d’un voyage en Angleterre.', 3),
    ('cd0e975c-66aa-5e9f-b4a9-f7ddbf20a6ba'::uuid, 'b48f6d6f-aef1-5aa2-85da-d58cddd5376e'::uuid, 'Quel philosophe anglais fonde le pouvoir sur un contrat et admet le droit de résistance ?', 'mcq', '["John Locke","Thomas Hobbes","David Hume","Adam Smith"]'::jsonb, 0, 'Traité du gouvernement civil, 1690.', 4),
    ('00b83a08-8d7c-5656-82be-5bf553e40841'::uuid, 'b48f6d6f-aef1-5aa2-85da-d58cddd5376e'::uuid, 'La lecture montesquienne du régime anglais est-elle exacte ?', 'mcq', '["Elle est en partie idéalisée : le cabinet mêle exécutif et législatif","Elle est parfaitement fidèle","Elle décrit la France","Elle porte sur la Hollande"]'::jsonb, 0, 'Le modèle vaut moins comme description que comme programme.', 5),
    ('ee98f5f3-cf8d-5dc6-8625-42a6f0b7f4b2'::uuid, 'b48f6d6f-aef1-5aa2-85da-d58cddd5376e'::uuid, 'L’Encyclopédie de Diderot et d’Alembert paraît au XVIIIe siècle.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'De 1751 à 1772, malgré interdictions et suspensions.', 6),
    ('c0305c2a-7314-5995-ab4b-4dd8772b4400'::uuid, 'b48f6d6f-aef1-5aa2-85da-d58cddd5376e'::uuid, 'Qu’admire surtout Voltaire dans la société anglaise ?', 'mcq', '["La tolérance religieuse et la liberté de commerce","La puissance de l’armée","La cour royale","Le système des corporations"]'::jsonb, 0, 'Il oppose la Bourse de Londres au fanatisme continental.', 7),
    ('331876b1-15a7-5aa2-8c39-27b1ea5e82d6'::uuid, 'b48f6d6f-aef1-5aa2-85da-d58cddd5376e'::uuid, 'Par quels lieux les idées des Lumières circulent-elles ?', 'mcq', '["Salons, cafés, académies et correspondances","Uniquement les universités","Les tribunaux","Les couvents"]'::jsonb, 0, 'Une sociabilité nouvelle, en marge des institutions officielles.', 8),
    ('fb9f59ab-3389-55b8-aa9a-e89d1b4376c6'::uuid, '027986b0-078f-5b02-8fae-f033b95b6f94'::uuid, 'Quel slogan résume la revendication des colons américains ?', 'mcq', '["Pas de taxation sans représentation","Liberté, égalité, fraternité","Le roi et la loi","Vive la république"]'::jsonb, 0, 'Ils réclament d’abord les droits des sujets britanniques.', 1),
    ('8d704984-21ff-54c0-8159-10cad9ae0d08'::uuid, '027986b0-078f-5b02-8fae-f033b95b6f94'::uuid, 'Quelle guerre pousse Londres à taxer davantage ses colonies ?', 'mcq', '["La guerre de Sept Ans","La guerre de Succession d’Espagne","La guerre de Crimée","La guerre de Cent Ans"]'::jsonb, 0, 'Achevée en 1763, elle laisse une dette considérable.', 2),
    ('e0b4f81a-aecd-5316-a107-76e12cade817'::uuid, '027986b0-078f-5b02-8fae-f033b95b6f94'::uuid, 'Quel événement de 1773 symbolise la révolte contre la taxe sur le thé ?', 'mcq', '["La Boston Tea Party","La bataille de Lexington","Le Stamp Act","Le siège de Yorktown"]'::jsonb, 0, 'Des caisses de thé jetées à la mer dans le port de Boston.', 3),
    ('accbb083-371f-5bb2-bd7a-2fe3af431788'::uuid, '027986b0-078f-5b02-8fae-f033b95b6f94'::uuid, 'Quand est proclamée la Déclaration d’indépendance ?', 'mcq', '["Le 4 juillet 1776","Le 14 juillet 1789","Le 19 octobre 1781","Le 3 septembre 1783"]'::jsonb, 0, 'Rédigée principalement par Thomas Jefferson.', 4),
    ('0671f301-fc3d-5fe4-9f22-f4513a2aa41e'::uuid, '027986b0-078f-5b02-8fae-f033b95b6f94'::uuid, 'Quelle bataille décide de la guerre d’Indépendance en 1781 ?', 'mcq', '["Yorktown","Saratoga","Bunker Hill","Trenton"]'::jsonb, 0, 'Avec le concours décisif de l’armée et de la flotte françaises.', 5),
    ('90a50c8d-186c-5af0-899b-ee3483e012b1'::uuid, '027986b0-078f-5b02-8fae-f033b95b6f94'::uuid, 'La Constitution américaine de 1787 abolit l’esclavage.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle le laisse subsister, et le compte même dans la représentation.', 6),
    ('e2ad168d-78c9-551e-869c-b1de2f499180'::uuid, '027986b0-078f-5b02-8fae-f033b95b6f94'::uuid, 'Quel principe hérité de Montesquieu structure la Constitution de 1787 ?', 'mcq', '["La séparation des pouvoirs","Le suffrage censitaire","La monarchie constitutionnelle","Le droit divin"]'::jsonb, 0, 'Un exécutif présidentiel, un Congrès, une Cour suprême.', 7),
    ('8f4e1f85-21c6-5994-83fd-2162a84dbc51'::uuid, '027986b0-078f-5b02-8fae-f033b95b6f94'::uuid, 'Quel pays européen soutient militairement les insurgés américains ?', 'mcq', '["La France","La Prusse","L’Autriche","La Russie"]'::jsonb, 0, 'Une revanche sur la guerre de Sept Ans, très coûteuse pour ses finances.', 8),
    ('55465ef6-2a96-52f4-b9f2-fbbf55db5e8d'::uuid, 'b9475df1-f522-599c-bf2a-bdf4973a3a48'::uuid, 'Qui place le Soleil au centre du système en 1543 ?', 'mcq', '["Copernic","Galilée","Kepler","Newton"]'::jsonb, 0, 'Son livre paraît l’année de sa mort.', 1),
    ('286cc53e-90b1-591d-bc2c-83886698b5fa'::uuid, 'b9475df1-f522-599c-bf2a-bdf4973a3a48'::uuid, 'Pourquoi Galilée est-il condamné en 1633 ?', 'mcq', '["Pour avoir défendu l’héliocentrisme","Pour avoir inventé le télescope","Pour avoir critiqué le roi d’Espagne","Pour ses travaux d’anatomie"]'::jsonb, 0, 'La science entre en conflit avec l’autorité religieuse.', 2),
    ('c6431d96-7b20-5748-8441-05c5f943c1b6'::uuid, 'b9475df1-f522-599c-bf2a-bdf4973a3a48'::uuid, 'Quelle loi Newton énonce-t-il dans les Principia de 1687 ?', 'mcq', '["La gravitation universelle","La conservation de la matière","La circulation du sang","La loi des gaz parfaits"]'::jsonb, 0, 'Une même loi pour la pomme et pour la Lune.', 3),
    ('03178d9d-4b17-57fa-9a9e-55e1f1924c27'::uuid, 'b9475df1-f522-599c-bf2a-bdf4973a3a48'::uuid, 'Quel savant français fonde la chimie moderne à la fin du XVIIIe siècle ?', 'mcq', '["Lavoisier","Buffon","Linné","Jenner"]'::jsonb, 0, 'Rien ne se perd, rien ne se crée : la matière se conserve.', 4),
    ('32005a2b-13cb-556f-9611-afe9a375dae5'::uuid, 'b9475df1-f522-599c-bf2a-bdf4973a3a48'::uuid, 'Quelle institution scientifique est fondée à Paris en 1666 ?', 'mcq', '["L’Académie royale des sciences","La Royal Society","Le Collège de France","L’Institut Pasteur"]'::jsonb, 0, 'Six ans après la Royal Society de Londres.', 5),
    ('83178877-aec6-5b31-999d-f41b32ab1c69'::uuid, 'b9475df1-f522-599c-bf2a-bdf4973a3a48'::uuid, 'Edward Jenner met au point la vaccination contre la variole en 1796.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'À partir de la vaccine contractée par les vachères.', 6),
    ('7cf0e0d5-a6ae-5c5d-9a6e-362adb455de8'::uuid, 'b9475df1-f522-599c-bf2a-bdf4973a3a48'::uuid, 'Quel instrument révèle au XVIIe siècle un monde invisible à l’œil nu ?', 'mcq', '["Le microscope","Le sextant","La boussole","L’astrolabe"]'::jsonb, 0, 'Comme le télescope pour le ciel, il fournit des faits nouveaux.', 7),
    ('a7d93d97-c0a4-5a8c-b90f-6da6b445204b'::uuid, 'b9475df1-f522-599c-bf2a-bdf4973a3a48'::uuid, 'Quel philosophe formule le doute méthodique ?', 'mcq', '["Descartes","Bacon","Locke","Hume"]'::jsonb, 0, 'Le Discours de la méthode, 1637.', 8),
    ('6d2760e3-431c-5b04-a6f8-2df031b31cc0'::uuid, 'e8754fb8-bbaa-5933-8e28-296f7d004086'::uuid, 'Que sont les enclosures ?', 'mcq', '["La clôture et le regroupement des terres pour une agriculture plus productive","Des ateliers textiles","Des taxes sur le blé","Des mines de charbon à ciel ouvert"]'::jsonb, 0, 'Elles augmentent les rendements et libèrent des bras pour la ville.', 1),
    ('0364b579-27c0-5158-ab89-540fdc8a5ce7'::uuid, 'e8754fb8-bbaa-5933-8e28-296f7d004086'::uuid, 'Qui perfectionne la machine à vapeur en 1769 ?', 'mcq', '["James Watt","Thomas Newcomen","Abraham Darby","Richard Arkwright"]'::jsonb, 0, 'Le condenseur séparé fait chuter la consommation de charbon.', 2),
    ('36818bf8-095a-5f40-b476-8d9b18978850'::uuid, 'e8754fb8-bbaa-5933-8e28-296f7d004086'::uuid, 'Quel combustible remplace le bois dans la sidérurgie anglaise ?', 'mcq', '["Le coke tiré du charbon","La tourbe","Le pétrole","Le gaz naturel"]'::jsonb, 0, 'Abraham Darby l’utilise dès 1709.', 3),
    ('52f89967-ec7e-5555-bdf4-794bda72bf98'::uuid, 'e8754fb8-bbaa-5933-8e28-296f7d004086'::uuid, 'Quelle industrie est la première transformée par la mécanisation ?', 'mcq', '["Le textile, notamment le coton","La construction navale","La chimie","L’imprimerie"]'::jsonb, 0, 'Navette volante, spinning jenny, mule-jenny.', 4),
    ('238cb520-c97c-5782-b26d-d56d0b663651'::uuid, 'e8754fb8-bbaa-5933-8e28-296f7d004086'::uuid, 'Qu’appelle-t-on la transition démographique ?', 'mcq', '["Le passage d’une forte mortalité à une mortalité basse, la natalité restant élevée un temps","L’exode rural","La hausse de l’émigration","Le vieillissement de la population"]'::jsonb, 0, 'Elle provoque une forte croissance de la population.', 5),
    ('a73ef6ba-fbc8-5a53-9349-3673ba37554b'::uuid, 'e8754fb8-bbaa-5933-8e28-296f7d004086'::uuid, 'Adam Smith publie La Richesse des nations en 1776.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La théorie libérale accompagne la révolution industrielle.', 6),
    ('2ca12366-c4ad-5f1c-b130-035fa1c6bee3'::uuid, 'e8754fb8-bbaa-5933-8e28-296f7d004086'::uuid, 'Quel dispositif juridique encourage l’invention en Angleterre ?', 'mcq', '["Le brevet","La corporation","Le monopole royal","La commende"]'::jsonb, 0, 'Il garantit à l’inventeur le profit de son idée.', 7),
    ('aee93751-75ee-5da8-bbb0-1b2e9ef02a8c'::uuid, 'e8754fb8-bbaa-5933-8e28-296f7d004086'::uuid, 'Qu’est-ce qui change dans l’organisation du travail avec la fabrique ?', 'mcq', '["Horaires imposés, surveillance et division des tâches","Le travail à domicile se généralise","Les corporations reprennent le contrôle","Le travail devient saisonnier"]'::jsonb, 0, 'La discipline d’usine est une nouveauté sociale majeure.', 8),
    ('9968a50e-ac61-5621-ae3b-dbdc64bc3edf'::uuid, '2e04fc88-cba6-5e8a-8ee6-32245adc7498'::uuid, 'Quelle part de la population française forme le tiers état ?', 'mcq', '["Plus de 97 %","Environ 60 %","Environ 80 %","Environ 50 %"]'::jsonb, 0, 'Clergé et noblesse réunis dépassent à peine 2 %.', 1),
    ('568dedb2-32f5-512f-b549-cc029a90e625'::uuid, '2e04fc88-cba6-5e8a-8ee6-32245adc7498'::uuid, 'Quel impôt le paysan verse-t-il à l’Église ?', 'mcq', '["La dîme","La taille","La gabelle","Le cens"]'::jsonb, 0, 'Prélevée en nature sur la récolte.', 2),
    ('ac8dded7-ce37-50b0-a09f-7993499d7692'::uuid, '2e04fc88-cba6-5e8a-8ee6-32245adc7498'::uuid, 'Que sont les banalités seigneuriales ?', 'mcq', '["L’obligation payante d’utiliser le four, le moulin ou le pressoir du seigneur","Des amendes judiciaires","Un impôt royal sur le sel","Des corvées routières d’État"]'::jsonb, 0, 'Un monopole seigneurial très mal supporté.', 3),
    ('16a994dc-ec1c-5ec0-81c5-4936a1a96e63'::uuid, '2e04fc88-cba6-5e8a-8ee6-32245adc7498'::uuid, 'Qu’appelle-t-on la réaction seigneuriale au XVIIIe siècle ?', 'mcq', '["La remise en vigueur de droits féodaux tombés en désuétude","Une révolte des seigneurs contre le roi","La vente des terres nobles","La suppression des corvées"]'::jsonb, 0, 'Elle nourrit la colère paysanne à la veille de 1789.', 4),
    ('6df6b4ab-aca1-57db-ab72-046ece8e43e0'::uuid, '2e04fc88-cba6-5e8a-8ee6-32245adc7498'::uuid, 'Qu’est-ce que la Grande Peur de l’été 1789 ?', 'mcq', '["Une vague de panique et de révolte dans les campagnes","Une épidémie de peste","Une famine urbaine","Une invasion étrangère"]'::jsonb, 0, 'Les paysans s’en prennent aux châteaux et aux terriers.', 5),
    ('f806984b-e3bb-52ef-9082-457d6f9b22ed'::uuid, '2e04fc88-cba6-5e8a-8ee6-32245adc7498'::uuid, 'La nuit du 4 août 1789 abolit les privilèges.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Droits féodaux et privilèges fiscaux tombent en une nuit.', 6),
    ('4b0802d3-5171-502d-a988-1507dc8223ce'::uuid, '2e04fc88-cba6-5e8a-8ee6-32245adc7498'::uuid, 'Qu’est-ce qu’un terrier seigneurial ?', 'mcq', '["Le registre des droits et redevances dus au seigneur","Une réserve de grain","Un tribunal de village","Une parcelle communale"]'::jsonb, 0, 'Le brûler, c’est effacer la preuve de la dette.', 7),
    ('a6100156-5cfd-55fe-9f54-cd5555543fce'::uuid, '2e04fc88-cba6-5e8a-8ee6-32245adc7498'::uuid, 'Quel événement climatique et agricole aggrave la crise de 1789 ?', 'mcq', '["Les mauvaises récoltes de 1788 et un hiver rigoureux","Une sécheresse en 1785","Des inondations en 1790","Une invasion de criquets"]'::jsonb, 0, 'Le prix du pain flambe au printemps 1789.', 8),
    ('04bed5b2-c464-52ba-8c7e-8ed5c7e88685'::uuid, '9c2077e6-3ec0-599f-915d-aeeeed340c56'::uuid, 'Quelle part des Français vit en ville au XVIIIe siècle ?', 'mcq', '["Environ 20 %","Environ 50 %","Environ 5 %","Environ 70 %"]'::jsonb, 0, 'La France reste massivement rurale.', 1),
    ('461646c7-96e9-59d1-b84a-505fcd4b13b3'::uuid, '9c2077e6-3ec0-599f-915d-aeeeed340c56'::uuid, 'Quels ports français s’enrichissent du commerce colonial ?', 'mcq', '["Bordeaux, Nantes et La Rochelle","Strasbourg et Lille","Lyon et Grenoble","Reims et Dijon"]'::jsonb, 0, 'La façade atlantique profite du sucre et de la traite.', 2),
    ('70ea1a46-eb8b-5d48-9a43-96124c2b1786'::uuid, '9c2077e6-3ec0-599f-915d-aeeeed340c56'::uuid, 'À quel ordre appartient juridiquement la bourgeoisie ?', 'mcq', '["Au tiers état","À la noblesse","Au clergé","À un quatrième ordre"]'::jsonb, 0, 'Riche mais sans privilège : d’où sa frustration politique.', 3),
    ('fcc02655-a5a1-5f44-808b-cdfbe3b59f3c'::uuid, '9c2077e6-3ec0-599f-915d-aeeeed340c56'::uuid, 'Quelle dépense pèse le plus lourd dans le budget du peuple urbain ?', 'mcq', '["Le pain","Le logement","Le vêtement","Le chauffage"]'::jsonb, 0, 'Il peut absorber la moitié d’un salaire en année de disette.', 4),
    ('5e581cdb-9ec2-5bb2-8f60-23a2212435f0'::uuid, '9c2077e6-3ec0-599f-915d-aeeeed340c56'::uuid, 'Où se forme l’opinion publique au XVIIIe siècle ?', 'mcq', '["Dans les cafés, salons, loges et cabinets de lecture","Dans les églises uniquement","À la cour de Versailles","Dans les corporations"]'::jsonb, 0, 'Une sociabilité neuve, hors du contrôle royal.', 5),
    ('6c0c781a-1509-5fe7-98da-19030916a075'::uuid, '9c2077e6-3ec0-599f-915d-aeeeed340c56'::uuid, 'Paris compte environ 600 000 habitants à la veille de la Révolution.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'De loin la plus grande ville du royaume.', 6),
    ('6e39fa7f-81f8-5ffc-8bfc-88e32817f2c3'::uuid, '9c2077e6-3ec0-599f-915d-aeeeed340c56'::uuid, 'Que sont les cahiers de doléances ?', 'mcq', '["Les demandes rédigées par les paroisses et les corps en vue des états généraux","Les registres fiscaux du roi","Les comptes des corporations","Les listes de mendiants"]'::jsonb, 0, 'Ceux des villes sont souvent les plus politiques.', 7),
    ('bd07bb8d-7545-53ec-bc2e-18559d4fdb06'::uuid, '9c2077e6-3ec0-599f-915d-aeeeed340c56'::uuid, 'Quel événement parisien du 14 juillet 1789 symbolise l’entrée du peuple urbain en politique ?', 'mcq', '["La prise de la Bastille","La fête de la Fédération","La journée des Tuiles","La marche sur Versailles"]'::jsonb, 0, 'Une forteresse presque vide, mais un symbole du pouvoir arbitraire.', 8),
    ('3065a9f9-4a40-59df-a351-2b22158956dd'::uuid, 'e755723b-1717-5e96-9477-4c8a20d949f2'::uuid, 'Comment définit-on un risque en géographie ?', 'mcq', '["Le croisement d’un aléa et d’une société vulnérable","Un phénomène naturel violent","Une catastrophe déjà survenue","Une zone inconstructible"]'::jsonb, 0, 'Sans population exposée, il n’y a pas de risque.', 1),
    ('765edcf5-bd56-5dfa-a9b0-076a198468d9'::uuid, 'e755723b-1717-5e96-9477-4c8a20d949f2'::uuid, 'Qu’est-ce que la vulnérabilité ?', 'mcq', '["La fragilité des populations et des biens face à un aléa","La violence d’un séisme","La fréquence d’un cyclone","La capacité à se reconstruire"]'::jsonb, 0, 'Elle dépend du bâti, des revenus, de l’organisation des secours.', 2),
    ('224c9b8b-f685-51fc-970a-d96626f36b59'::uuid, 'e755723b-1717-5e96-9477-4c8a20d949f2'::uuid, 'Qu’appelle-t-on la résilience d’un territoire ?', 'mcq', '["Sa capacité à se relever après une catastrophe","Sa richesse par habitant","Sa densité de population","Son taux d’urbanisation"]'::jsonb, 0, 'Elle se prépare avant la crise, pas seulement après.', 3),
    ('1ffa9f4f-b727-591b-bf47-d562710feff4'::uuid, 'e755723b-1717-5e96-9477-4c8a20d949f2'::uuid, 'Pourquoi un séisme de même magnitude est-il plus meurtrier en Haïti qu’au Japon ?', 'mcq', '["La vulnérabilité y est bien plus forte","L’aléa y est plus intense","Le sol y est plus fragile","La population y est plus dense"]'::jsonb, 0, 'Normes de construction, alerte et secours font la différence.', 4),
    ('23c0eba3-a88d-5716-9dd5-03dba5385b51'::uuid, 'e755723b-1717-5e96-9477-4c8a20d949f2'::uuid, 'Que s’est-il passé à Fukushima en 2011 ?', 'mcq', '["Un aléa naturel a déclenché un accident technologique","Une explosion industrielle isolée","Une pandémie","Une rupture de barrage"]'::jsonb, 0, 'Séisme, tsunami puis accident nucléaire : un risque hybride.', 5),
    ('deb5911d-f0c1-5b8b-9921-df730775957c'::uuid, 'e755723b-1717-5e96-9477-4c8a20d949f2'::uuid, 'Les pays du Sud concentrent l’essentiel des victimes des catastrophes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les pays du Nord concentrent en revanche l’essentiel des dégâts matériels.', 6),
    ('b0b84e3c-37e8-5167-aed6-ac4ee39ead26'::uuid, 'e755723b-1717-5e96-9477-4c8a20d949f2'::uuid, 'Que fait un plan de prévention des risques en France ?', 'mcq', '["Il réglemente ou interdit la construction dans les zones exposées","Il indemnise les sinistrés","Il organise les secours","Il finance la reconstruction"]'::jsonb, 0, 'C’est un outil d’aménagement, annexé au document d’urbanisme.', 7),
    ('36ef8fa9-08b0-522d-8279-d839e2cbf54a'::uuid, 'e755723b-1717-5e96-9477-4c8a20d949f2'::uuid, 'Quelle différence entre prévision et prévention ?', 'mcq', '["Prévoir, c’est annoncer l’aléa ; prévenir, c’est réduire la vulnérabilité","Ce sont deux synonymes","Prévoir concerne l’industrie, prévenir la nature","Prévenir, c’est indemniser"]'::jsonb, 0, 'L’une est scientifique, l’autre politique et technique.', 8),
    ('879ff266-cc57-5d0e-b1a5-86d0701183ee'::uuid, '01d4e0ac-890a-5182-977a-9e18dc917465'::uuid, 'Pourquoi les deltas asiatiques sont-ils très exposés au changement climatique ?', 'mcq', '["Faible altitude, très forte densité et moyens limités","Sols volcaniques instables","Absence de cours d’eau","Climat désertique"]'::jsonb, 0, 'Exposition et vulnérabilité s’y additionnent.', 1),
    ('3f929190-5d15-56eb-9839-8e4fed87cb68'::uuid, '01d4e0ac-890a-5182-977a-9e18dc917465'::uuid, 'Combien d’habitants compte environ le Bangladesh ?', 'mcq', '["Environ 170 millions","Environ 40 millions","Environ 600 millions","Environ 90 millions"]'::jsonb, 0, 'Sur un territoire plus petit que la moitié de la France.', 2),
    ('c8fd8247-fc06-5aa4-9492-2005cb69d2e8'::uuid, '01d4e0ac-890a-5182-977a-9e18dc917465'::uuid, 'Quel phénomène ruine les rizières côtières du delta ?', 'mcq', '["La salinisation des sols et des nappes","La désertification","Le gel hivernal","L’acidification des pluies"]'::jsonb, 0, 'Elle pousse certains paysans vers l’aquaculture de crevettes.', 3),
    ('31585d35-6b3a-5a19-9351-fd1624951809'::uuid, '01d4e0ac-890a-5182-977a-9e18dc917465'::uuid, 'Quelle forêt littorale protège naturellement le delta du Gange ?', 'mcq', '["La mangrove des Sundarbans","La forêt de teck","La taïga","La forêt de mousson du Deccan"]'::jsonb, 0, 'Elle amortit les vagues de tempête et fixe les sédiments.', 4),
    ('ebc1b6a7-d129-552c-9369-d9213b4506af'::uuid, '01d4e0ac-890a-5182-977a-9e18dc917465'::uuid, 'Qu’est-ce que l’adaptation, en matière de climat ?', 'mcq', '["Réduire les effets subis, par des digues, des abris ou des cultures adaptées","Réduire les émissions de gaz à effet de serre","Interdire les énergies fossiles","Déplacer les populations"]'::jsonb, 0, 'L’atténuation agit sur la cause, l’adaptation sur les conséquences.', 5),
    ('97b97062-3bc4-5947-9c58-5f6c3234fb69'::uuid, '01d4e0ac-890a-5182-977a-9e18dc917465'::uuid, 'L’accord de Paris sur le climat date de 2015.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il vise à contenir le réchauffement bien en dessous de 2 degrés.', 6),
    ('c1fbc428-4907-5bfe-a711-b189fa46cde8'::uuid, '01d4e0ac-890a-5182-977a-9e18dc917465'::uuid, 'Que désigne le GIEC ?', 'mcq', '["Le groupe d’experts qui fait la synthèse des connaissances sur le climat","Une agence de l’ONU pour les migrations","Un fonds d’aide aux pays pauvres","Un traité commercial"]'::jsonb, 0, 'Ses rapports servent de base aux négociations internationales.', 7),
    ('6a6c112d-5497-5a71-a429-ec83699f8135'::uuid, '01d4e0ac-890a-5182-977a-9e18dc917465'::uuid, 'Pourquoi parle-t-on d’injustice climatique à propos du Bangladesh ?', 'mcq', '["Il émet très peu de gaz à effet de serre et subit fortement les effets","Il refuse les accords internationaux","Il est le premier émetteur d’Asie","Il ne reçoit aucune aide"]'::jsonb, 0, 'Responsabilité faible, vulnérabilité maximale.', 8),
    ('c4216a42-ebe6-5f99-baae-042d425ab085'::uuid, 'beb7bf99-5a34-5b13-ae46-a91af852e03d'::uuid, 'Quelle est la superficie approximative de la forêt amazonienne ?', 'mcq', '["Environ 5,5 millions de km²","Environ 1 million de km²","Environ 12 millions de km²","Environ 500 000 km²"]'::jsonb, 0, 'Répartie sur neuf pays, dont 60 % au Brésil.', 1),
    ('c5ef0eaa-05c1-5eb4-a77f-cd37acd866fb'::uuid, 'beb7bf99-5a34-5b13-ae46-a91af852e03d'::uuid, 'Quelle est la première cause de déforestation en Amazonie ?', 'mcq', '["L’élevage bovin extensif","L’exploitation du bois précieux","L’urbanisation","Les barrages"]'::jsonb, 0, 'Le pâturage suit presque toujours la coupe.', 2),
    ('2caf3037-1a9d-5abe-9ac9-ec9bab20c534'::uuid, 'beb7bf99-5a34-5b13-ae46-a91af852e03d'::uuid, 'Quelle culture progresse fortement aux marges de la forêt ?', 'mcq', '["Le soja","Le blé","Le riz irrigué","La vigne"]'::jsonb, 0, 'Destinée surtout à l’alimentation animale et à l’exportation.', 3),
    ('b0157729-301c-5933-b901-fcf7faf3049f'::uuid, 'beb7bf99-5a34-5b13-ae46-a91af852e03d'::uuid, 'Quel rôle climatique majeur joue l’Amazonie ?', 'mcq', '["Elle stocke du carbone et alimente les pluies par évapotranspiration","Elle refroidit les océans","Elle produit l’essentiel de l’oxygène terrestre","Elle bloque les cyclones"]'::jsonb, 0, 'Sa disparition modifierait le régime des pluies du continent.', 4),
    ('caba4670-f671-5ff5-bf74-9b55cdbb9df0'::uuid, 'beb7bf99-5a34-5b13-ae46-a91af852e03d'::uuid, 'Qu’est-ce qu’un conflit d’usage ?', 'mcq', '["Une opposition entre acteurs qui veulent utiliser autrement un même espace","Un litige entre deux États","Un désaccord sur les frontières","Une grève des exploitants"]'::jsonb, 0, 'Éleveurs, autochtones, orpailleurs et ONG sur le même territoire.', 5),
    ('24e920d6-dee9-573a-b4f9-e6ac468ff4a5'::uuid, 'beb7bf99-5a34-5b13-ae46-a91af852e03d'::uuid, 'Les terres des peuples autochtones sont reconnues au Brésil.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Reconnues par la Constitution de 1988, mais souvent mal protégées sur le terrain.', 6),
    ('e569a98a-c399-5481-aa08-c5f0c7a4f001'::uuid, 'beb7bf99-5a34-5b13-ae46-a91af852e03d'::uuid, 'Quel outil permet de mesurer la déforestation en temps quasi réel ?', 'mcq', '["La surveillance satellitaire","Les recensements agricoles","Les enquêtes de terrain","Les registres fonciers"]'::jsonb, 0, 'Le Brésil dispose d’un des meilleurs systèmes au monde.', 7),
    ('5882d067-7335-5e55-b7de-325d71d8b326'::uuid, 'beb7bf99-5a34-5b13-ae46-a91af852e03d'::uuid, 'Qu’est-ce que l’agroforesterie ?', 'mcq', '["Associer cultures et arbres sur une même parcelle","Couper la forêt en bandes régulières","Replanter une seule essence","Interdire toute activité agricole"]'::jsonb, 0, 'Une des voies d’un développement moins destructeur.', 8),
