    ('1a52c914-37d4-593f-998b-6b1fc4e1ad73'::uuid, 'ccb4435a-a903-5e03-8b8d-d86d80c204dd'::uuid, 'Qu’appelle-t-on la fuite des cerveaux ?', 'mcq', '["Le départ des personnes les plus qualifiées d’un pays","Le retour des diplômés au pays","La formation des étudiants étrangers","Le recrutement local des ingénieurs"]'::jsonb, 0, 'Une perte pour le pays de départ, qui a financé leur formation.', 8),
    ('f827a3f6-94ca-5740-934c-11f9416efc35'::uuid, '21284598-39c5-506a-8e38-2017e02bb4de'::uuid, 'Qu’est-ce qui distingue un touriste d’un simple excursionniste ?', 'mcq', '["Le touriste passe au moins une nuit hors de son environnement habituel","Le touriste voyage à l’étranger","Le touriste paie un hébergement","Le touriste voyage en avion"]'::jsonb, 0, 'La nuitée est le critère retenu par les statistiques internationales.', 1),
    ('9ab40265-0ac2-55bd-9d7b-60a9834dbb4f'::uuid, '21284598-39c5-506a-8e38-2017e02bb4de'::uuid, 'Quelles régions captent l’essentiel des arrivées touristiques mondiales ?', 'mcq', '["Europe, Amérique du Nord et Asie orientale","Afrique et Amérique du Sud","Océanie et Asie centrale","Moyen-Orient uniquement"]'::jsonb, 0, 'Le tourisme mondial est très concentré.', 2),
    ('8a4c51d6-a12a-5352-8b4c-13f5443d2b08'::uuid, '21284598-39c5-506a-8e38-2017e02bb4de'::uuid, 'Sur quoi repose l’attractivité touristique des États-Unis ?', 'mcq', '["Des ressources naturelles et patrimoniales existantes, très diversifiées","Des équipements entièrement artificiels","La seule clientèle étrangère","Le tourisme religieux"]'::jsonb, 0, 'Parcs nationaux, métropoles, littoraux, parcs à thèmes.', 3),
    ('2fbf23d0-2780-5935-ab0c-9adabe0a380c'::uuid, '21284598-39c5-506a-8e38-2017e02bb4de'::uuid, 'Comment Dubaï est-elle devenue une destination majeure ?', 'mcq', '["En créant de toutes pièces des équipements spectaculaires","En protégeant un patrimoine ancien","En développant l’écotourisme désertique","En misant sur le tourisme de montagne"]'::jsonb, 0, 'Tours, îles artificielles, malls, hôtellerie de luxe.', 4),
    ('7c7cd1ef-14e8-57b9-9e4f-dba4b7adf92a'::uuid, '21284598-39c5-506a-8e38-2017e02bb4de'::uuid, 'Quel rôle joue la compagnie Emirates pour Dubaï ?', 'mcq', '["Elle fait de la ville un hub aérien entre Europe, Asie et Afrique","Elle finance les parcs naturels","Elle gère les hôtels de l’émirat","Elle exporte le pétrole"]'::jsonb, 0, 'La position de carrefour est au cœur de la stratégie.', 5),
    ('3c8dbde0-502b-593e-b582-7e6a05663be6'::uuid, '21284598-39c5-506a-8e38-2017e02bb4de'::uuid, 'Le tourisme représente environ un dixième du PIB mondial en comptant ses effets indirects.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Transport, hébergement, restauration, loisirs et leurs fournisseurs.', 6),
    ('fdd08d49-15a5-5e5d-9a04-92b65fc471a7'::uuid, '21284598-39c5-506a-8e38-2017e02bb4de'::uuid, 'Qu’est-ce que le surtourisme ?', 'mcq', '["Une fréquentation excessive qui dégrade le lieu et la vie des habitants","Un tourisme haut de gamme","Le tourisme hors saison","Le tourisme d’affaires"]'::jsonb, 0, 'Venise, Barcelone ou certains parcs nationaux en sont des exemples.', 7),
    ('98a3de16-d28b-5026-81e1-52ad25e06307'::uuid, '21284598-39c5-506a-8e38-2017e02bb4de'::uuid, 'Quelle contrainte environnementale pèse particulièrement sur Dubaï ?', 'mcq', '["La consommation d’eau dessalée et d’énergie pour la climatisation","Le manque de terrains constructibles","Le froid hivernal","La pollution des rivières"]'::jsonb, 0, 'Un modèle très coûteux en énergie.', 8),
    ('fa04be44-41ff-59e9-b6cc-d0244b768bb6'::uuid, 'c9c0f57f-f50b-58db-98e1-2944f0190dc4'::uuid, 'Qu’est-ce qu’une interface en géographie ?', 'mcq', '["Une zone de contact entre deux espaces différents, lieu d’échanges","Une frontière fermée","Un espace vide entre deux pays","Une zone économique exclusive"]'::jsonb, 0, 'La Méditerranée en est un exemple classique.', 1),
    ('8454261b-fef7-5034-9a7f-8a2ef30d3da2'::uuid, 'c9c0f57f-f50b-58db-98e1-2944f0190dc4'::uuid, 'Quelles sont les trois grandes routes migratoires méditerranéennes ?', 'mcq', '["Occidentale, centrale et orientale","Nord, Sud et Est","Atlantique, Adriatique et Égéenne","Maritime, terrestre et aérienne"]'::jsonb, 0, 'Elles se déplacent au gré des contrôles.', 2),
    ('91288064-0a10-5735-ba9e-769390343e9d'::uuid, 'c9c0f57f-f50b-58db-98e1-2944f0190dc4'::uuid, 'Que se passe-t-il lorsqu’une route migratoire est fermée par les contrôles ?', 'mcq', '["Les flux se reportent sur une autre route, souvent plus dangereuse","Les départs cessent","Les migrants rentrent chez eux","Les passeurs disparaissent"]'::jsonb, 0, 'Le durcissement allonge et renchérit les trajets.', 3),
