    ('47d4153a-6de8-5063-99f2-ee4a8c1c375b'::uuid, 'c9c0f57f-f50b-58db-98e1-2944f0190dc4'::uuid, 'Quel écart alimente les mobilités entre les deux rives ?', 'mcq', '["Un écart démographique et économique important","Un écart de superficie","Un écart climatique","Un écart linguistique"]'::jsonb, 0, 'Nord vieillissant et riche, Sud jeune et au chômage élevé.', 5),
    ('2134b278-d139-5498-a8f2-21c99a42104b'::uuid, 'c9c0f57f-f50b-58db-98e1-2944f0190dc4'::uuid, 'Les pays du Sud méditerranéen ne sont que des pays de départ.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils sont aussi des pays de transit et, de plus en plus, d’accueil.', 6),
