    ('06257036-455b-5539-a4d2-4758d1a25db4'::uuid, '6dea8b50-9600-5be2-af57-338c20eb6bd9'::uuid, 'De quelle énergie l’Afrique du Sud dépend-elle massivement ?', 'mcq', '["Le charbon","L’hydraulique","Le nucléaire","L’éolien"]'::jsonb, 0, 'D’où de fortes émissions et des coupures fréquentes.', 5),
