    ('1636de9e-197e-5dd7-aaca-be4ba0568128'::uuid, '6dea8b50-9600-5be2-af57-338c20eb6bd9'::uuid, 'Pourquoi les aires protégées créent-elles parfois des conflits ?', 'mcq', '["Elles limitent l’accès des populations riveraines aux ressources","Elles coûtent trop cher à l’État","Elles attirent trop peu de touristes","Elles sont mal délimitées juridiquement"]'::jsonb, 0, 'Conservation et besoins locaux doivent être conciliés.', 8),
    ('5287c93a-dfeb-53c0-b69c-c7794a890497'::uuid, '2e256048-26cd-5b5f-9314-1fe6db9c8be6'::uuid, 'Quel pays domine économiquement l’Afrique australe ?', 'mcq', '["L’Afrique du Sud","Le Mozambique","La Zambie","Le Malawi"]'::jsonb, 0, 'Industrie, mines, finance et services y sont concentrés.', 1),
    ('dfe3e7cb-ea55-56dc-89e7-496a4110b4e5'::uuid, '2e256048-26cd-5b5f-9314-1fe6db9c8be6'::uuid, 'Qu’était l’apartheid ?', 'mcq', '["Un régime de ségrégation légale des populations en Afrique du Sud","Un système de partage des terres","Une politique migratoire","Un accord commercial régional"]'::jsonb, 0, 'En vigueur de 1948 à 1991.', 2),
    ('66e0615a-155e-5317-a6ae-62d9fe800c7b'::uuid, '2e256048-26cd-5b5f-9314-1fe6db9c8be6'::uuid, 'Qui devient président de l’Afrique du Sud en 1994 ?', 'mcq', '["Nelson Mandela","Desmond Tutu","Thabo Mbeki","Frederik de Klerk"]'::jsonb, 0, 'Première élection au suffrage universel non racial.', 3),
    ('4e090c37-b3e7-5a00-b120-72e49f320de0'::uuid, '2e256048-26cd-5b5f-9314-1fe6db9c8be6'::uuid, 'Qu’est-ce qu’un township ?', 'mcq', '["Un quartier périphérique pauvre, hérité de la ségrégation","Un centre-ville d’affaires","Une réserve naturelle","Une zone industrielle"]'::jsonb, 0, 'Soweto en est l’exemple le plus connu.', 4),
    ('91749080-54a3-5763-b5a5-c652457e5c8c'::uuid, '2e256048-26cd-5b5f-9314-1fe6db9c8be6'::uuid, 'Quelle organisation régionale regroupe les États d’Afrique australe ?', 'mcq', '["La SADC","La CEDEAO","L’UEMOA","Le COMESA seul"]'::jsonb, 0, 'Communauté de développement d’Afrique australe.', 5),
    ('2bc0f983-176c-5550-ba59-7cc5ac386ef8'::uuid, '2e256048-26cd-5b5f-9314-1fe6db9c8be6'::uuid, 'L’Afrique du Sud est aujourd’hui un pays très égalitaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle reste l’un des pays les plus inégalitaires du monde.', 6),
    ('45d72220-2702-513d-8690-2fa30253d309'::uuid, '2e256048-26cd-5b5f-9314-1fe6db9c8be6'::uuid, 'Quel problème sanitaire a lourdement pesé sur l’espérance de vie régionale ?', 'mcq', '["L’épidémie de VIH","Le paludisme uniquement","Le choléra","La tuberculose seule"]'::jsonb, 0, 'Elle a fait reculer l’espérance de vie pendant des années.', 7),
    ('40736d79-0a30-515c-bfd5-631788ccd855'::uuid, '2e256048-26cd-5b5f-9314-1fe6db9c8be6'::uuid, 'Quel pays est souvent cité comme exemple de rente minière bien gérée ?', 'mcq', '["Le Botswana","Le Zimbabwe","L’Angola","La Zambie"]'::jsonb, 0, 'Les revenus du diamant y ont financé écoles et infrastructures.', 8),
    ('63c19a23-7daf-52c6-8b09-c7c979786fb6'::uuid, 'f16de316-5026-50c1-9882-058f2f0d641e'::uuid, 'Quelle activité a organisé les premières grandes migrations de travail dans la région ?', 'mcq', '["L’exploitation minière","Le tourisme","La pêche industrielle","La culture du coton"]'::jsonb, 0, 'Les mines du Witwatersrand recrutaient dans toute la région.', 1),
    ('d00908d5-fd51-5f84-947a-d46e59115a7c'::uuid, 'f16de316-5026-50c1-9882-058f2f0d641e'::uuid, 'Quel pays est aujourd’hui le principal pôle d’attraction migratoire régional ?', 'mcq', '["L’Afrique du Sud","La Zambie","La Namibie","Le Malawi"]'::jsonb, 0, 'Surtout depuis le Zimbabwe et le Mozambique.', 2),
    ('8ee8a131-7224-56a7-8287-47e048f4a5de'::uuid, 'f16de316-5026-50c1-9882-058f2f0d641e'::uuid, 'Quelle métropole concentre l’essentiel de cette attraction ?', 'mcq', '["Johannesburg","Windhoek","Gaborone","Lusaka"]'::jsonb, 0, 'Née de la mine, devenue la capitale économique régionale.', 3),
    ('78da398a-ee41-5b25-8caa-d44ab59a0c30'::uuid, 'f16de316-5026-50c1-9882-058f2f0d641e'::uuid, 'Qu’ont révélé les violences de 2008 et 2015 en Afrique du Sud ?', 'mcq', '["Des tensions xénophobes liées à la concurrence pour l’emploi","Un conflit frontalier","Une crise sanitaire","Une révolte étudiante"]'::jsonb, 0, 'La pauvreté et le chômage nourrissent le rejet des migrants.', 4),
    ('89cba219-3b20-5381-ae20-5152d537057e'::uuid, 'f16de316-5026-50c1-9882-058f2f0d641e'::uuid, 'Comment se fait principalement l’urbanisation dans la région ?', 'mcq', '["Par des quartiers informels, faute de logements abordables","Par des villes nouvelles planifiées","Par la densification des centres anciens","Par des lotissements pavillonnaires"]'::jsonb, 0, 'Avec des difficultés d’accès à l’eau et à l’électricité.', 5),
    ('1d0b3c9b-6b78-5f19-a1ec-bc0f7b6b9cf0'::uuid, 'f16de316-5026-50c1-9882-058f2f0d641e'::uuid, 'Les remises envoyées par les diasporas sont essentielles pour le Lesotho.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme pour le Zimbabwe : elles font vivre de nombreux ménages.', 6),
    ('fb329fa2-0250-5528-b5ce-5ac9cdcfdfe3'::uuid, 'f16de316-5026-50c1-9882-058f2f0d641e'::uuid, 'Quelle mobilité fait vivre les régions proches des parcs nationaux ?', 'mcq', '["Le tourisme international","La migration de travail","Les mobilités étudiantes","Le commerce transfrontalier"]'::jsonb, 0, 'Safaris, hébergement, guides et emplois indirects.', 7),
    ('65e3e8fa-3dca-5965-9d15-58fcb9dfe539'::uuid, 'f16de316-5026-50c1-9882-058f2f0d641e'::uuid, 'Quelle activité transfrontalière informelle est largement exercée par des femmes ?', 'mcq', '["Le petit commerce le long des corridors","L’extraction minière","Le transport routier","La pêche hauturière"]'::jsonb, 0, 'Une économie de la frontière peu visible dans les statistiques.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('histoire-geo');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('histoire-geo')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 279 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 279 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
